/* DSP boot stream redirection (research/sharc_dsp_patch_feasibility.md).
 *
 * The stock sender loop at 0x9d005e1c reads word s2 of the SHARC boot stream
 * at 0x9d0399e8 + 4 * s2. With the --dsp-voice-bend option the load at
 * 0x9d005e30 calls dsp_stream_fetch (dsp_stream_entry.S), which returns word
 * `index` of the rebuilt stream: pieces of the stock stream in flash and the
 * new data generated by tools/dsp_voice_bend.py (dsp_stream_data.h). */

#include <stdint.h>

struct dsp_segment {
    uint32_t end;          /* first word index after this segment */
    uint32_t start;        /* first word index of this segment */
    const uint32_t *words; /* the segment's words */
};

#include "dsp_stream_data.h"

uint32_t dsp_stream_word(uint32_t index)
{
    unsigned k;

    for (k = 0; k < sizeof dsp_segments / sizeof dsp_segments[0]; k++) {
        if (index < dsp_segments[k].end)
            return dsp_segments[k].words[index - dsp_segments[k].start];
    }
    return 0;
}
